package com.vr3th.mediacompressor.engine
import android.content.Context;import android.net.Uri;import androidx.documentfile.provider.DocumentFile
import com.vr3th.mediacompressor.data.ProcessResult;import com.vr3th.mediacompressor.utils.StorageUtils
import java.io.*;import java.util.zip.*
class ArchiveEngine(private val context:Context){
 fun compressToZip(uris:List<Uri>,archiveName:String):ProcessResult{val s=System.currentTimeMillis();var total=0L;val out=StorageUtils.createTempFile(context,"archive_",".zip");try{ZipOutputStream(BufferedOutputStream(FileOutputStream(out))).use{z->z.setLevel(Deflater.BEST_COMPRESSION);for(u in uris){val d=DocumentFile.fromSingleUri(context,u);val n=d?.name?:"file_${System.currentTimeMillis()}";total+=d?.length()?:0;z.putNextEntry(ZipEntry(n));context.contentResolver.openInputStream(u)?.use{it.copyTo(z)};z.closeEntry()}};return ProcessResult(true,archiveName,total,out.length(),"-","-",0,0,"${uris.size} Files","ZIP Deflate",System.currentTimeMillis()-s,out.absolutePath)}catch(x:Exception){return ProcessResult(false,archiveName,total,0,"-","-",0,0,"-","-",0,"",errorMessage=x.localizedMessage?:"Archive compression failed")}}
 fun extractZip(uri:Uri,originalName:String):ProcessResult{val s=System.currentTimeMillis();var orig=0L;context.contentResolver.openFileDescriptor(uri,"r")?.use{orig=it.statSize};var count=0;var total=0L;val dir=File(context.cacheDir,"extracted_${System.currentTimeMillis()}").apply{mkdirs()};try{context.contentResolver.openInputStream(uri)?.use{ZipInputStream(BufferedInputStream(it)).use{z->var e=z.nextEntry;while(e!=null){if(!e.isDirectory){val f=File(dir,e.name);f.parentFile?.mkdirs();FileOutputStream(f).use{z.copyTo(it)};count++;total+=f.length()};z.closeEntry();e=z.nextEntry}}};return ProcessResult(true,originalName,orig,total,"-","-",0,0,"ZIP Archive","$count Extracted Files",System.currentTimeMillis()-s,dir.absolutePath)}catch(x:Exception){return ProcessResult(false,originalName,orig,0,"-","-",0,0,"-","-",0,"",errorMessage=x.localizedMessage?:"Zip extraction failed")}}
}
